368	bool AttrAsBool(const AttrInfo &attr) {
369	  if (attr.dtype == "bool") {
370	    return attr.value_bool;
371	  }
372	  if (attr.dtype == "int" || attr.dtype == "int32" || attr.dtype == "int64") {
