1101	void CubeKernelTilingWrapper::BuildMatMulArgs(const std::vector<TensorInfo> &args_list, int input_num,
1102	                                              bool transpose_a, bool transpose_b,
1103	                                              std::vector<TensorInfo> &origin_inputs,
1104	                                              std::vector<TensorInfo> &origin_outputs,
1105	                                              std::vector<TensorInfo> &inputs) {
1106	  origin_inputs.clear();
1107	  origin_outputs.clear();
1108	  inputs.clear();
1109	
1110	  int64_t m = 0;
1111	  int64_t n = 0;
1112	  std::vector<int64_t> write_shape;
1113	
1114	  for (int i = 0; i < input_num && i < static_cast<int>(args_list.size()); ++i) {
1115	    TensorInfo input = args_list[i];
1116	    input.param_name = "input" + std::to_string(i);
1117	    input.ori_shape = input.shape;
1118	
1119	    origin_inputs.push_back(input);
1120	    inputs.push_back(input);
1121	
1122	    if (i == 0) {
1123	      write_shape = input.shape;
1124	      m = transpose_a ? input.shape[input.shape.size() - 1] : input.shape[input.shape.size() - 2];
1125	    } else if (i == 1) {
1126	      n = transpose_b ? input.shape[input.shape.size() - 2] : input.shape[input.shape.size() - 1];
1127	    }
1128	  }
1129	
1130	  if (args_list.size() >= 2) {
1131	    TensorInfo output = args_list[args_list.size() - 2];
1132	    output.param_name = "output0";
1133	    if (!write_shape.empty()) {
1134	      write_shape[write_shape.size() - 1] = n;
1135	      write_shape[write_shape.size() - 2] = m;
1136	      output.shape = write_shape;
1137	      output.ori_shape = write_shape;
1138	    }
1139	    if (!inputs.empty()) {
1140	      output.dtype = inputs.back().dtype;
1141	    }
1142	    origin_outputs.push_back(output);
1143	  }
1144	}
