1146	TilingResult CubeKernelTilingWrapper::DoMatMulTiling(const CompileInfo &compile_info,
1147	                                                     const std::vector<TensorInfo> &inputs,
1148	                                                     const std::vector<TensorInfo> &outputs,
1149	                                                     const std::vector<AttrInfo> &attrs, bool is_batch) {
1150	  TilingResult result;
1151	  if (AutofuseDoCubeMatMulTiling(&compile_info, &inputs, &outputs, &attrs, is_batch, &result)) {
1152	    FillTilingMeta(result, is_batch);
